pub enum Msg {
    Ping,
}

const CURRENT_VERSION: &str = "v1";

pub fn decode(bytes: &str) -> Result<Msg, String> {
    match bytes.trim() {
        "ping" | "v1:ping" => Ok(Msg::Ping),
        _ => Err("unknown".into()),
    }
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => format!("{}:ping", CURRENT_VERSION),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn decodes_current_ping() {
        assert!(matches!(decode("v1:ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn decodes_legacy_ping() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn rejects_payloads_that_only_contain_ping() {
        assert!(decode("not-a-ping").is_err());
    }

    #[test]
    fn encodes_current_ping() {
        assert_eq!(encode(&Msg::Ping), "v1:ping");
    }
}

